/* Directory handles stay in this origin's IndexedDB, never in exported vault JSON. */
window.recentFolders=(()=>{
 let dbPromise;const memory=new Map();
 const database=()=>dbPromise??=new Promise((resolve,reject)=>{const req=indexedDB.open('amago-projects',1);req.onupgradeneeded=()=>req.result.createObjectStore('projects',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});
 async function operation(mode,callback){const db=await database();return new Promise((resolve,reject)=>{const tx=db.transaction('projects',mode),req=callback(tx.objectStore('projects'));tx.oncomplete=()=>resolve(req?.result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
 async function entries(){try{for(const e of await operation('readonly',store=>store.getAll()))memory.set(e.id,e)}catch{}return [...memory.values()].sort((a,b)=>b.lastOpened.localeCompare(a.lastOpened)).slice(0,12)}
 async function remember(handle){const all=await entries();let previous;for(const e of all)try{if(await e.handle.isSameEntry(handle)){previous=e;break}}catch{}const record={id:previous?.id||crypto.randomUUID(),name:handle.name,path:handle.name,lastOpened:new Date().toISOString(),handle};memory.set(record.id,record);try{await operation('readwrite',store=>store.put(record));const stored=await operation('readonly',store=>store.getAll());for(const old of stored.sort((a,b)=>b.lastOpened.localeCompare(a.lastOpened)).slice(12))await operation('readwrite',store=>store.delete(old.id))}catch{record.sessionOnly=true}return record}
 return {remember,list:async()=>({projects:(await entries()).map(({handle,...info})=>info)}),forget:async id=>{memory.delete(id);await operation('readwrite',store=>store.delete(id));return {removed:true}},reopen:async id=>{const record=memory.get(id)||(await entries()).find(e=>e.id===id);if(!record)throw Error('Projeto recente indisponível. Selecione a pasta novamente.');const permission={mode:'readwrite'};if(await record.handle.queryPermission(permission)!=='granted'&&await record.handle.requestPermission(permission)!=='granted')throw Error('Acesso à pasta não concedido. Use Abrir pasta para selecionar novamente.');return record.handle}};
})();
